<style>
.xd305-projects-page{padding:0 0 72px;background:#f6f7f9;color:#191a1d}
.xd305-projects-container{width:var(--wide);margin-inline:auto}
.xd305-projects-breadcrumb{display:flex;flex-wrap:wrap;gap:12px;padding:26px 0;color:#626a73;font-size:12px}
.xd305-projects-breadcrumb a{color:#626a73}.xd305-projects-breadcrumb a:hover{color:#805009}
.xd305-projects-heading{padding:18px 0 36px;margin-bottom:36px;border-bottom:1px solid #e2e5e9}
.xd305-projects-kicker{display:flex;align-items:center;gap:12px;margin:0 0 16px;color:#805009;font-size:12px;font-weight:700;letter-spacing:.1em;text-transform:uppercase}
.xd305-projects-kicker:before{content:'';width:28px;height:3px;background:#f0a629}
.xd305-projects-heading h1{color:#191a1d;font-size:clamp(36px,4vw,52px);font-weight:700;line-height:1.15;letter-spacing:-.025em;margin:0 0 18px}
.xd305-projects-heading>p:last-child{max-width:700px;margin:0;color:#626a73;font-size:16px;line-height:1.8}
.xd305-projects-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}
.xd305-project-card{min-width:0;overflow:hidden;background:#fff;color:#202126;border:1px solid #dddde2;border-radius:10px;transition:transform .2s,box-shadow .2s}
.xd305-project-card:hover{transform:translateY(-4px);box-shadow:0 12px 32px #0003}
.xd305-project-image{display:block;overflow:hidden;aspect-ratio:16/10;background:#242429}
.xd305-project-image img{display:block;width:100%;height:100%;object-fit:cover;transition:transform .3s}
.xd305-project-card:hover img{transform:scale(1.04)}
.xd305-project-copy{padding:26px}
.xd305-project-copy h2{color:#202126;font-size:21px;font-weight:700;line-height:1.4;margin:0 0 14px;letter-spacing:normal;text-transform:none}
.xd305-project-copy h2 a{display:flex;align-items:start;justify-content:space-between;gap:16px;color:inherit}
.xd305-project-copy h2 a:hover{color:#805009}.xd305-project-arrow{flex-shrink:0;color:#805009;font-size:22px}
.xd305-project-copy p{margin:0;color:#5c6069;font-size:14px;line-height:1.8;overflow-wrap:anywhere}
.xd305-projects-empty{grid-column:1/-1;padding:32px;border:1px solid #e2e5e9;border-radius:10px;color:#626a73;background:#fff}
.xd305-projects-pagination{margin-top:36px;color:#626a73}.xd305-projects-pagination svg{width:20px;height:20px}.xd305-projects-pagination a{color:#805009}
.xd305-projects-page a:focus-visible{outline:3px solid #98620c;outline-offset:3px}
@media(max-width:900px){.xd305-projects-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:600px){.xd305-projects-page{padding-bottom:48px}.xd305-projects-container{width:calc(100% - 30px)}.xd305-projects-heading{padding:8px 0 28px;margin-bottom:28px}.xd305-projects-heading h1{font-size:36px}.xd305-projects-heading>p:last-child{font-size:15px}.xd305-projects-grid{grid-template-columns:minmax(0,1fr)}.xd305-project-copy{padding:24px 20px}}
@media(prefers-reduced-motion:reduce){.xd305-project-card,.xd305-project-image img{transition:none}.xd305-project-card:hover,.xd305-project-card:hover img{transform:none}}
</style>
